float rand(vec2 co){ return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453); }

float conway(vec2 co, sampler2D tex)
{
    float self = texelFetch(tex, ivec2(co), 0).x;

    int neighbors = int(round(
        texelFetch(tex, ivec2(co) + ivec2(-1.0, -1.0), 0).x +
        texelFetch(tex, ivec2(co) + ivec2(-1.0, 0.0), 0).x +
        texelFetch(tex, ivec2(co) + ivec2(-1.0, 1.0), 0).x +
        texelFetch(tex, ivec2(co) + ivec2(0.0, 1.0), 0).x +
        texelFetch(tex, ivec2(co) + ivec2(1.0, 1.0), 0).x +
        texelFetch(tex, ivec2(co) + ivec2(1.0, 0.0), 0).x +
        texelFetch(tex, ivec2(co) + ivec2(1.0, -1.0), 0).x +
        texelFetch(tex, ivec2(co) + ivec2(0.0, -1.0), 0).x
        ));

    switch (neighbors)
    {
        case 0: return 0.0;
        case 1: return 0.0;
        case 2: return max(self, 0.0);
        case 3: return 1.0;
    }

    return 0.0;
}

vec3 conway3(vec2 co, sampler2D tex)
{
    vec3 self = texelFetch(tex, ivec2(co), 0).rgb;

    int neighbors_x = int(round(
