        texelFetch(tex, ivec2(co) + ivec2(0.0, -1.0), 0).y
        ));
    int neighbors_z = int(round(
        texelFetch(tex, ivec2(co) + ivec2(-1.0, -1.0), 0).z +
        texelFetch(tex, ivec2(co) + ivec2(-1.0, 0.0), 0).z +
