        texelFetch(tex, ivec2(co) + ivec2(0.0, -1.0), 0).z
        ));

    float res_x = 0.0;
    float res_y = 0.0;
    float res_z = 0.0;

    switch (neighbors_x)
    {
        case 0: res_x = 0.0;
        case 1: res_x = 0.0;
        case 2: res_x = max(self.x, 0.0);
        case 3: res_x = 1.0;
    }

    switch (neighbors_y)
    {
        case 0: res_y = 0.0;
        case 1: res_y = 0.0;
        case 2: res_y = max(self.y, 0.0);
        case 3: res_y = 1.0;
    }

    switch (neighbors_z)
    {
        case 0: res_z = 0.0;
        case 1: res_z = 0.0;
        case 2: res_z = max(self.z, 0.0);
        case 3: res_z = 1.0;
    }

    return vec3(res_x, res_y, res_z);
}

